for(const [id,kind,label] of [['soap','cloud','clouds'],['lotion','dapple','canopy light']]){const panel=document.querySelector('.product-'+id);if(!panel)continue;const surfaces=[panel.querySelector('.product-visual'),panel.querySelector('.scene-backdrop')];const canvases=surfaces.map(s=>{const c=document.createElement('canvas');c.className='ambient-motion';c.setAttribute('aria-hidden','true');s.append(c);return c;});const button=document.createElement('button');button.type='button';button.className='water-control';panel.querySelector('.product-copy').append(button);SFEnvironment({kind,source:panel.querySelector('.product-visual img'),surfaces,canvases,button,panel,observe:document.querySelector('.scene-pin'),label});}
